\set ON_ERROR_STOP on
BEGIN;
SET LOCAL search_path TO schoolnet,public;
CREATE FUNCTION pg_temp.assert_true(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAILED: %',label; END IF; RAISE NOTICE 'PASS: %',label; END $$;
CREATE FUNCTION pg_temp.expect_failure(statement text,fragment text,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN IF position(lower(fragment) IN lower(SQLERRM))=0 THEN RAISE EXCEPTION 'Unexpected failure for %: %',label,SQLERRM; END IF; RAISE NOTICE 'PASS: %',label; RETURN; END;
 RAISE EXCEPTION 'FAILED: % unexpectedly succeeded',label; END $$;
DO $$ DECLARE actor bigint; trainer bigint; learner bigint; coord bigint; outsider bigint; p bigint; p_other bigint; s bigint; template bigint; plan10 bigint; plan2 bigint; plan4 bigint; today_batch bigint; attendance_actor bigint; future_status text; revised bigint; a bigint; b bigint; c bigint; d bigint; trainees bigint[]='{}'; t bigint; att bigint; ass bigint; payload jsonb; first_payload jsonb; today date=(now() AT TIME ZONE 'Asia/Kolkata')::date;
BEGIN
 SELECT id INTO actor FROM app_user WHERE role='Administrator' AND active ORDER BY id LIMIT 1;
 SELECT id INTO trainer FROM app_user WHERE role='Trainer' AND active ORDER BY id LIMIT 1;
 IF actor IS NULL OR trainer IS NULL THEN RAISE EXCEPTION 'Initialize and seed local demo data before running verification.'; END IF;
 PERFORM set_actor(actor);
 INSERT INTO app_user(username,name,password_hash,role) VALUES('__verify_learner','Test Learner','unused','Trainee') RETURNING id INTO learner;
 INSERT INTO app_user(username,name,password_hash,role) VALUES('__verify_coordinator','Test Coordinator','unused','Coordinator') RETURNING id INTO coord;
 p=save_master('project',0,'{"name":"Acceptance test project","code":"__VERIFY","description":"","active":true}',actor);
 p_other=save_master('project',0,'{"name":"Other acceptance project","code":"__VERIFY_OTHER","description":"","active":true}',actor);
 INSERT INTO user_project VALUES(coord,p);
 SELECT id INTO s FROM school WHERE active ORDER BY id LIMIT 1;
 INSERT INTO project_school VALUES(p,s),(p_other,s);
 template=save_master('template',0,'{"name":"Acceptance form","questions":[{"id":"q1","label":"Confidence","type":"Rating","required":true,"choices":[]}]}',actor);
 payload=jsonb_build_object('plan_code','__VERIFY10','plan_name','Ten day acceptance plan','number_of_days',10,'template_id',template,'days',(SELECT jsonb_agg(jsonb_build_object('title','Day '||n,'topics','Classroom topics','feedback_template_version_id',CASE WHEN n IN(1,10) THEN template::text ELSE '' END)) FROM generate_series(1,10) n));
 plan10=save_plan(0,payload,actor); CALL publish_plan(plan10,actor);
 PERFORM pg_temp.assert_true((SELECT count(*)=10 AND min(day_number)=1 AND max(day_number)=10 FROM trainingplandetails WHERE training_plan_id=plan10),'AC01 complete ten-day plan');
 PERFORM pg_temp.assert_true(NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='schoolnet' AND table_name IN('trainingplan','trainingplandetails') AND data_type='date'),'AC01 plans have no calendar dates');
 PERFORM pg_temp.assert_true((SELECT count(*)=2 FROM trainingplandetails WHERE training_plan_id=plan10 AND activity_type='Feedback') AND (SELECT count(*)=8 FROM trainingplandetails WHERE training_plan_id=plan10 AND activity_type='Classroom training'),'AC02 boundary feedback and intermediate classroom days');
 plan2=save_plan(0,jsonb_build_object('plan_code','__VERIFY2','plan_name','Two day plan','number_of_days',2,'template_id',template),actor); CALL publish_plan(plan2,actor);
 PERFORM pg_temp.assert_true((SELECT count(*)=2 AND bool_and(activity_type='Feedback') FROM trainingplandetails WHERE training_plan_id=plan2),'AC03 two-day feedback plan');
 plan4=save_plan(0,jsonb_build_object('plan_code','__VERIFY4','plan_name','Four day plan','number_of_days',4,'template_id',template),actor);
 PERFORM pg_temp.assert_true((SELECT count(*)=4 AND min(day_number)=1 AND max(day_number)=4 FROM trainingplandetails WHERE training_plan_id=plan4),'Four-day plan contains exactly days 1 to 4');
 PERFORM pg_temp.assert_true((SELECT title='Pre form' AND activity_type='Feedback' FROM trainingplandetails WHERE training_plan_id=plan4 AND day_number=1) AND (SELECT title='Feedback' AND activity_type='Feedback' FROM trainingplandetails WHERE training_plan_id=plan4 AND day_number=4) AND (SELECT count(*)=2 FROM trainingplandetails WHERE training_plan_id=plan4 AND day_number IN(2,3) AND activity_type='Classroom training'),'Four-day plan Pre form, two classroom days and final Feedback');
 PERFORM save_plan(plan4,jsonb_build_object('plan_code','__VERIFY4','plan_name','Updated four day plan','number_of_days',2,'template_id',template),actor);
 PERFORM pg_temp.assert_true((SELECT count(*)=2 FROM trainingplandetails WHERE training_plan_id=plan4),'Resizing draft removes extra days');
 PERFORM save_plan(plan4,jsonb_build_object('plan_code','__VERIFY4','plan_name','Updated four day plan','number_of_days',4,'template_id',template),actor);
 PERFORM pg_temp.assert_true((SELECT count(*)=4 FROM trainingplandetails WHERE training_plan_id=plan4),'Updated draft saves exactly four days');
 PERFORM pg_temp.expect_failure(format('SELECT save_plan(%s,%L::jsonb,%s)',plan4,jsonb_build_object('plan_code','__VERIFY4','plan_name','Bad row count','number_of_days',4,'days',jsonb_build_array(jsonb_build_object('title','Only one day')))::text,actor),'one activity','Mismatched plan row count rejected');
 PERFORM pg_temp.assert_true((SELECT count(*)=4 FROM trainingplandetails WHERE training_plan_id=plan4),'Rejected row count preserves saved draft');
 revised=revise_plan(plan10,actor); DELETE FROM trainingplandetails WHERE training_plan_id=revised AND day_number=3;
 PERFORM pg_temp.expect_failure(format('CALL publish_plan(%s,%s)',revised,actor),'missing','AC04 missing day publication rejected');
 PERFORM pg_temp.expect_failure(format('UPDATE trainingplandetails SET topics=''changed'' WHERE training_plan_id=%s',plan10),'immutable','Published shared plan content is immutable');
 FOR n IN 1..30 LOOP
 t=save_master('trainee',0,jsonb_build_object('username','__verify'||n,'name','Test Teacher '||n,'mobile','912345'||lpad(n::text,4,'0'),'email','verify'||n||'@example.com','project_id',p,'school_id',s,'active',true,'user_id',CASE WHEN n=1 THEN learner::text ELSE '' END),actor);
 trainees=array_append(trainees,t); END LOOP;
 payload=jsonb_build_object('code','__VERIFY_A','name','Acceptance A','project_id',p,'school_id',s,'training_plan_id',plan10,'number_of_days',10,'start_date',today-10,'end_date',today-1,'trainer_id',trainer);
 a=save_batch(0,payload,actor); payload=payload||jsonb_build_object('code','__VERIFY_B','name','Acceptance B','start_date',today+30,'end_date',today+39); b=save_batch(0,payload,actor);
 CALL assign_trainees(a,trainees,actor); CALL assign_trainees(b,trainees,actor);
 PERFORM pg_temp.assert_true((SELECT count(*)=2 FROM batch WHERE id IN(a,b) AND training_plan_id=plan10),'AC05-AC07 two batches reference one shared plan with separate dates');
 PERFORM pg_temp.assert_true((SELECT count(*)=300 FROM attendance at JOIN batch_assignment ba ON ba.id=at.assignment_id WHERE ba.batch_id=a) AND (SELECT count(*)=300 FROM attendance at JOIN batch_assignment ba ON ba.id=at.assignment_id WHERE ba.batch_id=b),'AC09 thirty trainees initialize 300 attendance entries per batch');
 PERFORM pg_temp.expect_failure(format('SELECT save_batch(0,%L::jsonb,%s)',(payload||'{"code":"__BAD","number_of_days":9}'::jsonb)::text,actor),'duration','AC08 duration mismatch rejected');
 PERFORM pg_temp.expect_failure(format('SELECT save_batch(0,%L::jsonb,%s)',(payload||jsonb_build_object('code','__BAD','end_date',today+40))::text,actor),'end date','AC08 end-date mismatch rejected');
 PERFORM pg_temp.expect_failure(format('CALL assign_trainees(%s,ARRAY[%s]::bigint[],%s)',a,trainees[1],actor),'duplicate','AC16 duplicate assignment rejected');
 t=save_master('trainee',0,jsonb_build_object('username','__outsider','name','Outsider','mobile','9123456789','email','outsider@example.com','project_id',p_other,'school_id',s,'active',true,'user_id',''),actor);
 PERFORM pg_temp.expect_failure(format('CALL assign_trainees(%s,ARRAY[%s]::bigint[],%s)',a,t,actor),'eligible','AC17 project mismatch rejected');
 CALL transition_batch(a,'Scheduled','',actor); CALL transition_batch(b,'Scheduled','',actor);
 payload=payload||jsonb_build_object('code','__VERIFY_C','name','Overlapping','start_date',today+31,'end_date',today+40); c=save_batch(0,payload,actor);
 PERFORM pg_temp.expect_failure(format('CALL assign_trainees(%s,ARRAY[%s]::bigint[],%s)',c,trainees[1],actor),'overlapping','AC17 scheduled overlap rejected');
 SELECT at.id,ba.id INTO att,ass FROM attendance at JOIN batch_assignment ba ON ba.id=at.assignment_id JOIN trainingplandetails pd ON pd.training_plan_detail_id=at.training_plan_detail_id WHERE ba.batch_id=a AND ba.trainee_id=trainees[1] AND pd.day_number=1;
 first_payload=jsonb_build_array(jsonb_build_object('id',att,'revision',0,'status','Present','remarks',''));
 CALL save_attendance(a,1,first_payload,'Historical test',actor);
 PERFORM pg_temp.assert_true((SELECT bool_and(at.status='Not marked') FROM attendance at JOIN batch_assignment ba ON ba.id=at.assignment_id WHERE ba.batch_id=b),'AC10 shared batch attendance remains separate');
 CALL save_attendance(a,1,jsonb_build_array(jsonb_build_object('id',att,'revision',1,'status','Present','remarks','')),'Repeated save',actor);
 PERFORM pg_temp.assert_true((SELECT count(*)=300 FROM attendance at JOIN batch_assignment ba ON ba.id=at.assignment_id WHERE ba.batch_id=a),'AC16 repeated attendance does not duplicate records');
 PERFORM pg_temp.expect_failure(format('CALL save_attendance(%s,1,%L::jsonb,''Stale save'',%s)',a,first_payload::text,actor),'another session','Concurrent stale attendance rejected');
 CALL submit_feedback(ass,1,'{"q1":"4"}','Offline initial feedback',actor); CALL submit_feedback(ass,10,'{"q1":"5"}','Offline final feedback',actor);
 PERFORM pg_temp.assert_true((SELECT count(*)=2 FROM feedback_submission WHERE assignment_id=ass),'AC11 separate initial and final submissions');
 PERFORM pg_temp.assert_true((SELECT at.status='Not marked' FROM attendance at JOIN trainingplandetails pd ON pd.training_plan_detail_id=at.training_plan_detail_id WHERE at.assignment_id=ass AND pd.day_number=10),'AC18 feedback does not change attendance');
 PERFORM pg_temp.expect_failure(format('CALL submit_feedback(%s,1,''{}''::jsonb,''Offline test'',%s)',ass,actor),'required','Required feedback question enforced');
 PERFORM pg_temp.expect_failure(format('CALL submit_feedback(%s,1,''{"q1":"6"}''::jsonb,''Offline test'',%s)',ass,actor),'between 1 and 5','Rating validation enforced');
 PERFORM pg_temp.assert_true((SELECT status='Draft' AND version_number=2 FROM trainingplan WHERE training_plan_id=revised) AND (SELECT training_plan_id=plan10 FROM batch WHERE id=a),'AC12 revision keeps original batch references');
 payload=jsonb_build_object('code','__VERIFY_D','name','Draft changes','project_id',p,'school_id',s,'training_plan_id',plan10,'number_of_days',10,'start_date',today+60,'end_date',today+69,'trainer_id',trainer);
 d=save_batch(0,payload,actor); CALL assign_trainees(d,ARRAY[trainees[1],trainees[2]],actor);
 payload=payload||jsonb_build_object('start_date',today+61,'end_date',today+70); PERFORM save_batch(d,payload,actor);
 PERFORM pg_temp.assert_true((SELECT start_date=today+61 FROM batch WHERE id=d) AND (SELECT start_date=today+30 FROM batch WHERE id=b),'AC13 draft date change leaves other batches unchanged');
 payload=payload||jsonb_build_object('training_plan_id',plan2,'number_of_days',2,'end_date',today+62); PERFORM save_batch(d,payload,actor);
 PERFORM pg_temp.assert_true((SELECT count(*)=4 FROM attendance at JOIN batch_assignment ba ON ba.id=at.assignment_id WHERE ba.batch_id=d) AND (SELECT count(*)=2 FROM batch_assignment WHERE batch_id=d),'AC14 plan switch reconciles attendance and preserves roster');
 PERFORM pg_temp.expect_failure(format('SELECT save_batch(%s,%L::jsonb,%s)',a,payload::text,actor),'Draft','AC15 scheduled training setup is locked');
 PERFORM pg_temp.expect_failure(format('CALL transition_batch(%s,''Completed'','''',%s)',a,actor),'Not marked','AC19 unmarked attendance blocks completion');
 PERFORM pg_temp.expect_failure(format('CALL save_attendance(%s,1,''[]''::jsonb,'''',%s)',b,actor),'future','AC23 future attendance rejected');
 SELECT jsonb_agg(jsonb_build_object('id',at.id,'revision',at.revision,'status','Present','remarks','Tampered future entry')) INTO first_payload FROM attendance at JOIN batch_assignment ba ON ba.id=at.assignment_id JOIN trainingplandetails pd ON pd.training_plan_detail_id=at.training_plan_detail_id WHERE ba.batch_id=b AND pd.day_number=1;
 FOREACH attendance_actor IN ARRAY ARRAY[actor,coord,trainer] LOOP
  FOREACH future_status IN ARRAY ARRAY['Present','Absent'] LOOP
   SELECT jsonb_agg(value||jsonb_build_object('status',future_status)) INTO first_payload FROM jsonb_array_elements(first_payload);
   PERFORM pg_temp.expect_failure(format('CALL save_attendance(%s,1,%L::jsonb,''Admin override attempt'',%s)',b,first_payload::text,attendance_actor),'future','Future populated attendance blocked for staff and administrator');
  END LOOP;
 END LOOP;
 PERFORM pg_temp.assert_true(NOT EXISTS(SELECT 1 FROM attendance at JOIN batch_assignment ba ON ba.id=at.assignment_id WHERE ba.batch_id=b AND (at.status<>'Not marked' OR at.revision<>0 OR at.marked_at IS NOT NULL OR at.remarks<>'')),'Rejected future writes leave status, revision and history unchanged');
 today_batch=save_batch(0,jsonb_build_object('code','__VERIFY_TODAY','name','Current day attendance','project_id',p,'school_id',s,'training_plan_id',plan2,'number_of_days',2,'start_date',today,'end_date',today+1,'trainer_id',trainer),actor);
 CALL assign_trainees(today_batch,ARRAY[trainees[1]],actor); CALL transition_batch(today_batch,'Scheduled','',actor);
 SELECT jsonb_agg(jsonb_build_object('id',at.id,'revision',at.revision,'status','Present','remarks','Today is permitted')) INTO first_payload FROM attendance at JOIN batch_assignment ba ON ba.id=at.assignment_id JOIN trainingplandetails pd ON pd.training_plan_detail_id=at.training_plan_detail_id WHERE ba.batch_id=today_batch AND pd.day_number=1;
 CALL save_attendance(today_batch,1,first_payload,'',trainer);
 PERFORM pg_temp.assert_true(EXISTS(SELECT 1 FROM attendance at JOIN batch_assignment ba ON ba.id=at.assignment_id WHERE ba.batch_id=today_batch AND at.status='Present' AND at.marked_by=trainer),'Trainer can mark today without a correction reason');
 SELECT jsonb_agg(jsonb_build_object('id',at.id,'revision',at.revision,'status','Absent','remarks','Tomorrow attempt')) INTO first_payload FROM attendance at JOIN batch_assignment ba ON ba.id=at.assignment_id JOIN trainingplandetails pd ON pd.training_plan_detail_id=at.training_plan_detail_id WHERE ba.batch_id=today_batch AND pd.day_number=2;
 PERFORM pg_temp.expect_failure(format('CALL save_attendance(%s,1,%L::jsonb,''Forged current-day request'',%s)',today_batch,first_payload::text,actor),'outside','Future attendance record cannot be submitted as today');
 PERFORM pg_temp.expect_failure(format('CALL save_attendance(%s,2,%L::jsonb,'''',%s)',today_batch,first_payload::text,actor),'future','Future derived day blocked even when batch starts today');
 SELECT id INTO outsider FROM batch_assignment WHERE batch_id=a AND trainee_id=trainees[2];
 PERFORM pg_temp.expect_failure(format('CALL submit_feedback(%s,1,''{"q1":"4"}''::jsonb,'''',%s)',outsider,learner),'denied','AC20 another trainee feedback is denied');
 PERFORM pg_temp.assert_true(NOT can_project(coord,p_other),'Coordinator cannot access unassigned project');
 PERFORM pg_temp.expect_failure(format('SELECT save_batch(0,%L::jsonb,%s)',(payload||jsonb_build_object('code','__DENIED','project_id',p_other))::text,coord),'permission','Coordinator write scope enforced');
 SELECT ba.id INTO outsider FROM batch_assignment ba WHERE ba.batch_id=b LIMIT 1;
 PERFORM pg_temp.expect_failure(format('INSERT INTO attendance(assignment_id,training_plan_detail_id) SELECT %s,training_plan_detail_id FROM trainingplandetails WHERE training_plan_id=%s LIMIT 1',outsider,plan2),'different','AC22 attendance activity must belong to batch plan');
 CALL archive_plan(plan10,actor);
 PERFORM pg_temp.expect_failure(format('SELECT save_batch(0,%L::jsonb,%s)',(payload||jsonb_build_object('code','__ARCHIVE','training_plan_id',plan10,'number_of_days',10,'end_date',today+70))::text,actor),'Published','AC21 archived plan cannot be newly selected');
 PERFORM pg_temp.assert_true((SELECT training_plan_id=plan10 FROM batch WHERE id=a),'AC21 existing batch retains archived plan');
 FOR day IN 1..10 LOOP
 SELECT jsonb_agg(jsonb_build_object('id',at.id,'revision',at.revision,'status','Present','remarks','')) INTO payload FROM attendance at JOIN batch_assignment ba ON ba.id=at.assignment_id JOIN trainingplandetails pd ON pd.training_plan_detail_id=at.training_plan_detail_id WHERE ba.batch_id=a AND pd.day_number=day;
 CALL save_attendance(a,day,payload,'Resolve remaining test attendance',actor); END LOOP;
 CALL transition_batch(a,'Completed','',actor); PERFORM pg_temp.assert_true((SELECT status='Completed' FROM batch WHERE id=a),'Batch completes after attendance resolved and end date elapsed');
 PERFORM pg_temp.assert_true(EXISTS(SELECT 1 FROM audit_log WHERE entity='feedback_submission' AND actor_id=actor AND reason='Offline initial feedback'),'Feedback audit retains actor and reason');
END $$;
ROLLBACK;
